function render() {
  var todos = loadTodos();
  var filter = getActiveFilter();

  // Filter todos
  var filtered = todos.filter(function (todo) {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  });

  // ── In-place list update ──────────────────────────
  // Build map of existing items by id
  var existingLis = todoList.querySelectorAll('li');
  var existingMap = {};
  for (var i = 0; i < existingLis.length; i++) {
    existingMap[existingLis[i].dataset.id] = existingLis[i];
  }

  // Build set of filtered todo ids
  var filteredIds = {};
  for (var i = 0; i < filtered.length; i++) {
    filteredIds[filtered[i].id] = true;
  }

  // Remove items not in filtered set
  for (var id in existingMap) {
    if (!filteredIds[id]) {
      todoList.removeChild(existingMap[id]);
    }
  }

  // Add or update items in correct order
  for (var i = 0; i < filtered.length; i++) {
    var todo = filtered[i];
    var li = existingMap[todo.id];
    if (li) {
      // Update existing element in place (preserves DOM reference)
      if (todo.completed) {
        li.classList.add('completed');
      } else {
        li.classList.remove('completed');
      }
      li.querySelector('.toggle').checked = todo.completed;
      li.querySelector('label').textContent = todo.title;
      li.querySelector('.edit').value = todo.title;
      // Ensure correct position
      var cur = todoList.children[i];
      if (cur !== li) {
        todoList.insertBefore(li, cur || null);
      }
    } else {
      // Create new element
      var newLi = createTodoElement(todo);
      todoList.insertBefore(newLi, todoList.children[i] || null);
    }
  }

  // Update count
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

  // Show/hide main and footer
  var hasTodos = todos.length > 0;
  mainSection.style.display = hasTodos ? '' : 'none';
  footerSection.style.display = hasTodos ? '' : 'none';

  // Toggle-all state
  var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
  toggleAllCheckbox.checked = allCompleted;

  // Clear completed visibility
  var hasCompleted = todos.some(function (t) { return t.completed; });
  clearCompletedBtn.style.display = hasCompleted ? '' : 'none';

  // Active filter link
  filterLinks.forEach(function (link) {
    var linkHash = link.getAttribute('href');
    if (filter === 'all' && linkHash === '#/') link.classList.add('selected');
    else if (filter === 'active' && linkHash === '#/active') link.classList.add('selected');
    else if (filter === 'completed' && linkHash === '#/completed') link.classList.add('selected');
    else link.classList.remove('selected');
  });
}

